// ui/routes/team-policy/policy.mjs — feature "team-policy" (docs/team-policy.md). Generated by tools/split-by-feature.mjs v1;
// the body of register() was moved verbatim from ui/server.mjs. Edit it here from now on.
import { defaultGuardrailSetId, readGuardrailSet } from '../../../src/core/guardrail-store.mjs';
import { actorOf } from '../../../src/core/identity.mjs';
import { cachedTeamFor, skipReasonText } from '../../../src/core/mcp/registry.mjs';
import { parseScopeParam } from '../../../src/core/metrics/read.mjs';
import { capSummary, deviationsFor, fieldsForRun, mcpDeviations, skillDeviations as policySkillDeviations } from '../../../src/core/policy/effective.mjs';
import { WORCA_VERSION as POLICY_WORCA_VERSION, blockedPluginFindings, installedPluginsMap, mcpRequirements, pluginRequirements, skillRequirements } from '../../../src/core/policy/local.mjs';
import { normalizePolicyDoc } from '../../../src/core/policy/registry.mjs';
import { policyForScope, policyPayload } from '../../../src/core/policy/scope.mjs';
import { discoverAllPolicies, listPolicyScopes, publishPolicy, resolveProjectPolicy } from '../../../src/core/policy/sync.mjs';
import { resolveSkillRegistry as policySkillRegistry } from '../../../src/core/skills-registry/resolve.mjs';
import { skillSkipReasonText as policySkillWhy } from '../../../src/core/skills-registry/texts.mjs';
import fs from 'node:fs';
import { badRequest, mcpRunPreview, mcpTargetOf, parseMcpOptOut, sendPolicyError } from '../../server.mjs';

export function register(app) {

app.get('/api/policy/scopes', async (req, res) => {
  try {
    const scopes = await listPolicyScopes({ discover: req.query.discover === '1' });
    // The Plugins page strip and the setup checklist: every home's requirements, folded.
    const docs = [];
    for (const s of scopes.projects) if (s.home && !docs.some((d) => d.slug === s.home)) {
      const r = await resolveProjectPolicy(s.path, { discover: false }).catch(() => null);
      if (r?.ok) docs.push({ slug: r.home, doc: r.doc });
    }
    // MCP and skill rows from the policy cache — the source the consent routes hash against (MCP registry spec §11.3,
    // skills registry spec §5).
    res.json({ ...scopes, requirements: pluginRequirements(docs), blockedPlugins: blockedPluginFindings(docs), mcpRequirements: await mcpRequirements(), skillRequirements: await skillRequirements() });
  } catch (err) { sendPolicyError(res, err); }
});

/** Skills registry §2b-13: the Team set's skill deviations for a run on `target` — P3's resolver over the target, its
 *  Team set from the policy cache as the MCP half takes it (`cachedTeamFor`), worded with the resolver's skip text. */
async function policySkillNotes(fields, target, optOut = []) {
  const project = target.kind === 'project';
  const team = await cachedTeamFor(project ? { projectKey: target.key } : { workspaceId: target.id });
  const result = await policySkillRegistry({ surface: 'pipeline', targets: [target], teams: { [project ? target.key : `ws:${target.id}`]: team }, optOut });
  return policySkillDeviations(fields, result, (s) => policySkillWhy(s));
}

app.get('/api/policy', async (req, res) => {
  const scope = parseScopeParam(req.query.scope);
  if (!scope) return badRequest(res, 'scope must be project:<projectKey> or workspace:<workspaceId>');
  try {
    const { meta, r, workspaceRun, projectDir } = await policyForScope(scope);
    if (!r.ok) return res.status(404).json({ error: r.detail || `no team policy for this ${scope.kind}`, code: (r.code || r.reason || 'NOT_ENABLED').toString().toUpperCase().replace(/-/g, '_'), scope: meta });
    const payload = await policyPayload(meta, r, { workspaceRun, projectDir });
    // MCP registry spec §11.4: the off-policy card also lists the Team set's MCP deviations for this scope's runs,
    // worded and guarded like /api/policy/notes (a registry fault adds none; the policy's own card still paints).
    const fields = fieldsForRun(r.doc, { workspaceRun });
    if (fields['mcp.required']) {
      try {
        const target = await mcpTargetOf(scope.kind === 'project' ? { projectKey: scope.id } : { workspaceId: scope.id });
        if (target) { const p = await mcpRunPreview(target); payload.deviations.push(...mcpDeviations(fields, p.result, (sk) => skipReasonText(sk, p.catalog))); }
      } catch { /* a registry fault adds no MCP deviations */ }
    }
    if (fields['skills.required']) {
      try {
        const target = await mcpTargetOf(scope.kind === 'project' ? { projectKey: scope.id } : { workspaceId: scope.id });
        if (target) payload.deviations.push(...(await policySkillNotes(fields, target)));
      } catch { /* a registry fault adds no skill deviations; the policy's own card still paints */ }
    }
    res.json(payload);
  } catch (err) { sendPolicyError(res, err); }
});

// New pipeline form (board 8): the notes for a selection — caps, off-policy picks, plugin gaps.
app.get('/api/policy/notes', async (req, res) => {
  const scope = parseScopeParam(req.query.scope);
  if (!scope) return badRequest(res, 'scope must be project:<projectKey> or workspace:<workspaceId>');
  try {
    // MCP registry (§6.2): the form's opt-out, comma-joined like `models`, adds the MCP deviations. A
    // repeated parameter arrives as an array and is checked entry by entry; any other shape is a 400.
    const rawOptOut = req.query.mcpOptOut;
    const optOut = parseMcpOptOut(rawOptOut == null || rawOptOut === '' ? null : typeof rawOptOut === 'string' ? rawOptOut.split(',') : rawOptOut);
    if (optOut.error) return badRequest(res, optOut.error);
    const { meta, r, workspaceRun } = await policyForScope(scope);
    if (!r.ok) return res.json({ scope: meta, policy: null, notes: [] });
    const fields = fieldsForRun(r.doc, { workspaceRun });
    const guardrailsId = typeof req.query.guardrailsId === 'string' && req.query.guardrailsId ? req.query.guardrailsId : defaultGuardrailSetId();
    const set = await readGuardrailSet(guardrailsId);
    const models = typeof req.query.models === 'string' && req.query.models ? req.query.models.split(',').filter(Boolean).map((m) => ({ role: null, model: m })) : [];
    const dev = deviationsFor(fields, { guardrailsId, guardrailSet: set, stepModels: models, installed: installedPluginsMap(), worcaVersion: POLICY_WORCA_VERSION, metricsRecord: null });
    if (fields['mcp.required']) {
      try {
        const target = await mcpTargetOf(scope.kind === 'project' ? { projectKey: scope.id } : { workspaceId: scope.id });
        if (target) {
          const p = await mcpRunPreview(target, { optOut: optOut.list, models: models.map((m) => m.model) });
          dev.push(...mcpDeviations(fields, p.result, (sk) => skipReasonText(sk, p.catalog)));
        }
      } catch { /* a registry fault adds no MCP notes; the policy's own notes still paint */ }
    }
    if (fields['skills.required']) {
      try {
        const target = await mcpTargetOf(scope.kind === 'project' ? { projectKey: scope.id } : { workspaceId: scope.id });
        if (target) dev.push(...(await policySkillNotes(fields, target, optOut.list)));
      } catch { /* a registry fault adds no skill notes */ }
    }
    res.json({ scope: meta, policy: { home: r.home, sha: r.sha, delegated: r.delegated, from: r.from, caps: capSummary(r.doc, { workspaceRun }) }, notes: dev, guardrailsDefault: fields['guardrails.default']?.value ?? null });
  } catch (err) { sendPolicyError(res, err); }
});

// Publish (board 5): one commit to the home's worca-policy branch; a rejection comes back verbatim.
app.put('/api/policy', async (req, res) => {
  const scope = parseScopeParam(req.body?.scope);
  if (!scope) return badRequest(res, 'scope must be project:<projectKey> or workspace:<workspaceId>');
  if (!req.body || typeof req.body.doc !== 'object' || req.body.doc === null) return badRequest(res, 'doc must be the policy document');
  try {
    const { r } = await policyForScope(scope);
    if (!r.ok) return res.status(404).json({ error: r.detail || 'no team policy for this scope', code: 'NOT_ENABLED' });
    if (!r.homeDir || !fs.existsSync(r.homeDir)) return res.status(409).json({ error: `the policy home ${r.home} is not checked out on this machine`, code: 'NOT_HOME' });
    const out = await publishPolicy(r.homeDir, req.body.doc, { message: typeof req.body.message === 'string' ? req.body.message : null, by: actorOf(req) });
    res.json({ ok: true, slug: out.slug, sha: out.sha, unchanged: !!out.unchanged, doc: out.doc });
  } catch (err) { sendPolicyError(res, err); }
});

// Validate without publishing (the editor's live check): the normaliser's warnings, if any.
app.post('/api/policy/validate', (req, res) => {
  const { doc, warnings, unknownSchema } = normalizePolicyDoc(req.body?.doc);
  res.json({ ok: !!doc && !unknownSchema && warnings.length === 0, warnings, doc });
});

app.post('/api/policy/discover', async (_req, res) => {
  try { await discoverAllPolicies({ force: true }); res.json(await listPolicyScopes()); }
  catch (err) { sendPolicyError(res, err); }
});
}
